    public const int MaxErasureListTake = 100;
    public static int ComputeDaysRemaining(DateTimeOffset? t){if(t is null)return 0;int d=(int)Math.Floor((t.Value-TimeProvider.System.GetUtcNow()).TotalDays);return d<0?0:d;}
    public static string NormalizeSlug(string slug){ArgumentException.ThrowIfNullOrWhiteSpace(slug);return slug.Trim().ToLowerInvariant();}
    public static int ClampErasureListTake(int take)=>Math.Clamp(take,1,MaxErasureListTake);
    public static bool CanApproveTenantErasure(TenantRecord t){ArgumentNullException.ThrowIfNull(t);return t.OffboardedUtc is not null&&t.TenantErasureApprovedUtc is null;}
    public static bool CanStartTenantErasureOffboard(TenantRecord t){ArgumentNullException.ThrowIfNull(t);return t.OffboardedUtc is null;}
    public static bool CanRestoreTenantErasureQuarantine(TenantRecord t){ArgumentNullException.ThrowIfNull(t);return t.OffboardedUtc is not null;}
    public static bool CanSetTenantErasureLegalHold(DateTimeOffset h,DateTimeOffset n)=>h>n;
    public static bool CanClearTenantErasureLegalHold(TenantRecord t){ArgumentNullException.ThrowIfNull(t);return t.LegalHoldUntilUtc is not null;}
    public static bool IsEligibleForOrphanedCatalogCleanup(TenantRecord t,DateTimeOffset n,DateTimeOffset b){ArgumentNullException.ThrowIfNull(t);return t.TenantErasureRequestedUtc is not null&&t.TenantErasureRequestedUtc<=b&&t.TenantErasureApprovedUtc is not null&&(t.LegalHoldUntilUtc is null||t.LegalHoldUntilUtc<=n);}
    public static void ThrowIfTrialExpired(DateTimeOffset? e,DateTimeOffset n){if(e is{ }x&&x<=n)throw new TrialLimitExceededException(TrialLimitReason.Expired,ComputeDaysRemaining(e));}
    public static void ThrowIfTrialRunsExceeded(int u,int l,DateTimeOffset? e){if(u>=l)throw new TrialLimitExceededException(TrialLimitReason.RunsExceeded,ComputeDaysRemaining(e));}
    public static void ThrowIfTrialSeatsExceeded(int u,int l,DateTimeOffset? e){if(u>=l)throw new TrialLimitExceededException(TrialLimitReason.SeatsExceeded,ComputeDaysRemaining(e));}
